|width        = {{dv|{{tip|er|icononly = true}} {{tt|100|Initial width}}|{{tt|140|Width after redirection}}}}
|speed        = {{dv|{{tt|1200|Initial missile}}|{{tt|2500|Missile speed after redirection}}}}
|effect radius= {{tip|cr|icononly = true}} {{tt|180|Explosion radius from collision point, for both initial and redirected star (estimated)}}
